#include <algorithm>
#include <cmath>
#include <string>
#include <vector>

struct Vector2 { float x, y; };
struct Rectangle { float x, y, width, height; };
struct Brick { Rectangle r; int hp; };

struct Game
{
    std::vector<Brick> bricks;
    Rectangle paddle{ 350, 420, 100, 12 };
    Vector2 ball{ 400, 414 }, vel{ 0, 0 };
    float radius{ 6 };
    bool stuck{ true };
    int lives{ 3 }, score{ 0 };
    bool gameOver{ false };
};

namespace
{
    bool circleRect(Vector2 c, float r, const Rectangle& rect)
    {
        const float nx{ std::clamp(c.x, rect.x, rect.x + rect.width) };
        const float ny{ std::clamp(c.y, rect.y, rect.y + rect.height) };
        return (c.x - nx) * (c.x - nx) + (c.y - ny) * (c.y - ny) <= r * r;
    }

    void sitOnPaddle(Game& g)
    {
        g.ball = { g.paddle.x + g.paddle.width / 2, g.paddle.y - g.radius };
    }
}

Game makeGame(const std::vector<std::string>& rows)
{
    Game g;
    for (std::size_t r{ 0 }; r < rows.size(); ++r)
        for (std::size_t c{ 0 }; c < rows[r].size(); ++c)
        {
            const char ch{ rows[r][c] };
            if (ch >= '1' && ch <= '9')
                g.bricks.push_back({ { 40.0f + 60.0f * static_cast<float>(c), 40.0f + 20.0f * static_cast<float>(r), 60, 20 }, ch - '0' });
        }
    return g;
}

void launch(Game& g)
{
    if (!g.stuck) return;
    g.stuck = false;
    g.vel = { 0, -360 };
}

void update(Game& g, float paddleDir, float dt)
{
    if (g.gameOver) return;
    g.paddle.x = std::clamp(g.paddle.x + paddleDir * 480.0f * dt, 0.0f, 800.0f - g.paddle.width);
    if (g.stuck) { sitOnPaddle(g); return; }

    g.ball.x += g.vel.x * dt;
    g.ball.y += g.vel.y * dt;
    const float r{ g.radius };
    if (g.ball.x - r < 0) { g.ball.x = r; g.vel.x = std::fabs(g.vel.x); }
    if (g.ball.x + r > 800) { g.ball.x = 800 - r; g.vel.x = -std::fabs(g.vel.x); }
    if (g.ball.y - r < 0) { g.ball.y = r; g.vel.y = std::fabs(g.vel.y); }

    if (g.vel.y > 0 && circleRect(g.ball, r, g.paddle))
    {
        const float speed{ std::sqrt(g.vel.x * g.vel.x + g.vel.y * g.vel.y) };
        const float half{ g.paddle.width / 2 };
        const float offset{ std::clamp((g.ball.x - (g.paddle.x + half)) / half, -1.0f, 1.0f) };
        const float angle{ offset * 60.0f * 3.14159265f / 180.0f };
        g.vel = { speed * std::sin(angle), -speed * std::cos(angle) };
        g.ball.y = g.paddle.y - r;
    }

    for (Brick& b : g.bricks)
    {
        if (b.hp <= 0 || !circleRect(g.ball, r, b.r)) continue;
        --b.hp;
        g.score += b.hp == 0 ? 10 : 1;
        const float ox{ std::min(g.ball.x + r, b.r.x + b.r.width) - std::max(g.ball.x - r, b.r.x) };
        const float oy{ std::min(g.ball.y + r, b.r.y + b.r.height) - std::max(g.ball.y - r, b.r.y) };
        if (ox < oy)
        {
            const bool left{ g.ball.x < b.r.x + b.r.width / 2 };
            g.vel.x = left ? -std::fabs(g.vel.x) : std::fabs(g.vel.x);
            g.ball.x += left ? -ox : ox;
        }
        else
        {
            const bool above{ g.ball.y < b.r.y + b.r.height / 2 };
            g.vel.y = above ? -std::fabs(g.vel.y) : std::fabs(g.vel.y);
            g.ball.y += above ? -oy : oy;
        }
        break;
    }

    if (g.ball.y - r > 450)
    {
        --g.lives;
        if (g.lives <= 0) { g.gameOver = true; return; }
        g.stuck = true;
        g.vel = { 0, 0 };
        sitOnPaddle(g);
    }
}

int bricksLeft(const Game& g)
{
    return static_cast<int>(std::count_if(g.bricks.begin(), g.bricks.end(), [](const Brick& b) { return b.hp > 0; }));
}

unitTests:
bool at(Rectangle r, float x, float y) { return std::fabs(r.x - x) < 1e-4f && std::fabs(r.y - y) < 1e-4f; }
TEST("layout") {
    const Game g = makeGame({ "1.2", "..3" });
    CHECK_EQ(g.bricks.size(), std::size_t{ 3 }); CHECK(at(g.bricks[0].r, 40, 40)); CHECK_EQ(g.bricks[0].hp, 1);
    CHECK(at(g.bricks[1].r, 160, 40)); CHECK_EQ(g.bricks[1].hp, 2); CHECK(at(g.bricks[2].r, 160, 60)); CHECK_EQ(g.bricks[2].hp, 3); CHECK_EQ(bricksLeft(g), 3);
}
TEST("the ball rides the paddle") {
    Game g = makeGame({}); update(g, 1, 0.1f); CHECK_NEAR(g.paddle.x, 398.0, 1e-3); CHECK_NEAR(g.ball.x, 448.0, 1e-3); CHECK_NEAR(g.ball.y, 414.0, 1e-3);
    update(g, -1, 10); CHECK_NEAR(g.paddle.x, 0.0, 1e-3); CHECK_NEAR(g.ball.x, 50.0, 1e-3);
    launch(g); CHECK(!g.stuck); CHECK_NEAR(g.vel.y, -360.0, 1e-3);
}
TEST("walls") {
    Game g = makeGame({}); g.stuck = false;
    g.ball = { 5, 200 }; g.vel = { -100, 0 }; update(g, 0, 0.01f); CHECK_NEAR(g.ball.x, 6.0, 1e-3); CHECK(g.vel.x > 0);
    g.ball = { 797, 200 }; g.vel = { 100, 0 }; update(g, 0, 0.01f); CHECK_NEAR(g.ball.x, 794.0, 1e-3); CHECK(g.vel.x < 0);
    g.ball = { 300, 5 }; g.vel = { 0, -100 }; update(g, 0, 0.01f); CHECK_NEAR(g.ball.y, 6.0, 1e-3); CHECK(g.vel.y > 0);
}
TEST("paddle aims the ball") {
    Game g = makeGame({}); g.stuck = false;
    g.ball = { 400, 412 }; g.vel = { 0, 300 }; update(g, 0, 0.01f); CHECK_NEAR(g.vel.x, 0.0, 1e-3); CHECK_NEAR(g.vel.y, -300.0, 1e-2); CHECK_NEAR(g.ball.y, 414.0, 1e-3);
    g.ball = { 450, 415 }; g.vel = { 0, 300 }; update(g, 0, 0.001f); CHECK_NEAR(g.vel.x, 259.81, 1e-1); CHECK_NEAR(g.vel.y, -150.0, 1e-1);
    g.ball = { 400, 418 }; g.vel = { 0, -300 }; update(g, 0, 0.001f); CHECK(g.vel.y < 0); CHECK_NEAR(g.vel.y, -300.0, 1e-3);
}
TEST("a brick hit from below") {
    Game g = makeGame({ "2" }); g.stuck = false;
    g.ball = { 70, 68 }; g.vel = { 0, -300 }; update(g, 0, 0.01f);
    CHECK_EQ(g.bricks[0].hp, 1); CHECK_EQ(g.score, 1); CHECK(g.vel.y > 0); CHECK_NEAR(g.ball.y, 66.0, 1e-3);
    g.ball = { 70, 68 }; g.vel = { 0, -300 }; update(g, 0, 0.01f); CHECK_EQ(g.score, 11); CHECK_EQ(bricksLeft(g), 0);
}
TEST("a brick hit from the side") {
    Game g = makeGame({ "1" }); g.stuck = false;
    g.ball = { 34, 50 }; g.vel = { 300, 0 }; update(g, 0, 0.01f);
    CHECK_EQ(g.bricks[0].hp, 0); CHECK(g.vel.x < 0); CHECK_NEAR(g.ball.x, 34.0, 1e-3);
}
TEST("one brick per update") { Game g = makeGame({ "11" }); g.stuck = false; g.ball = { 100, 66 }; g.vel = { 0, -300 }; update(g, 0, 0.01f); CHECK_EQ(g.bricks[0].hp, 0); CHECK_EQ(g.bricks[1].hp, 1); }
TEST("losing balls") {
    Game g = makeGame({ "1" }); g.stuck = false;
    g.ball = { 300, 455 }; g.vel = { 0, 300 }; update(g, 0, 0.01f);
    CHECK_EQ(g.lives, 2); CHECK(g.stuck); CHECK_NEAR(g.ball.x, 400.0, 1e-3); CHECK_NEAR(g.ball.y, 414.0, 1e-3);
    for (int i = 0; i < 2; ++i) { g.stuck = false; g.ball = { 300, 455 }; g.vel = { 0, 300 }; update(g, 0, 0.01f); }
    CHECK_EQ(g.lives, 0); CHECK(g.gameOver); const float x = g.paddle.x; update(g, 1, 1); CHECK_NEAR(g.paddle.x, x, 1e-6);
}

